//! Markdown normalization report generation.

use crate::types::{CrossTableRelationship, TableDataDto};

pub fn generate_report(
    tables: &[TableDataDto],
    relationships: &[CrossTableRelationship],
) -> String {
    let mut md = String::from("# Database Normalization Report\n\n");
    md.push_str(&format!(
        "Generated by the **NormaFlow Rust engine** on {}.\n\n",
        chrono_like_timestamp()
    ));
    md.push_str(&format!("- **Tables processed**: {}\n", tables.len()));
    md.push_str(&format!(
        "- **Cross-table relationships detected**: {}\n",
        relationships.len()
    ));
    md.push_str(&format!(
        "- **Total rows**: {}\n\n",
        tables.iter().map(|t| t.row_count).sum::<usize>()
    ));

    md.push_str("## 1. Table schemas\n\n");
    for table in tables {
        md.push_str(&format!(
            "### `{}` ({})\n\n",
            table.table_name, table.file_name
        ));
        md.push_str(
            "| Column | Inferred type | Semantic entity | Confidence | Distinct (sampled) |\n",
        );
        md.push_str("| :--- | :--- | :--- | ---: | ---: |\n");
        for tag in &table.ner_tags {
            let col_type = table
                .column_types
                .get(
                    table
                        .headers
                        .iter()
                        .position(|h| h == &tag.column_name)
                        .unwrap_or(usize::MAX),
                )
                .map(String::as_str)
                .unwrap_or("TEXT");
            md.push_str(&format!(
                "| `{}` | `{col_type}` | {} | {:.0}% | — |\n",
                tag.column_name,
                tag.description,
                tag.confidence * 100.0
            ));
        }
        let pk = table.primary_key.join(", ");
        md.push_str(&format!("\n**Primary key candidate**: `{pk}`\n"));
        if table.skipped_rows > 0 {
            md.push_str(&format!(
                "**Malformed rows skipped**: {}\n",
                table.skipped_rows
            ));
        }
        md.push('\n');
    }

    md.push_str("## 2. Detected cross-table relationships\n\n");
    if relationships.is_empty() {
        md.push_str("*No cross-table foreign keys were detected.*\n");
    } else {
        md.push_str(
            "| Referencing | Column | Referenced | Column | Cardinality | Confidence | Method |\n",
        );
        md.push_str("| :--- | :--- | :--- | :--- | :--- | ---: | :--- |\n");
        for rel in relationships {
            md.push_str(&format!(
                "| `{}` | `{}` | `{}` | `{}` | {} | {:.0}% | {} |\n",
                rel.source_table,
                rel.source_column,
                rel.target_table,
                rel.target_column,
                rel.cardinality,
                rel.confidence * 100.0,
                rel.detected_by
            ));
        }
    }

    md.push_str("\n## 3. Notes\n\n");
    md.push_str("- SQL types are inferred from sampled values; review before production use.\n");
    md.push_str("- Primary keys default to the first column when no stronger evidence exists.\n");
    md
}

fn chrono_like_timestamp() -> String {
    // Avoid pulling an extra chrono dependency: emit seconds since epoch in a
    // readable ISO-ish form using std only.
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    format!("<epoch:{secs}>")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::EntityTag;

    #[test]
    fn report_contains_sections() {
        use crate::types::TableDataDto;
        let tables = vec![TableDataDto {
            table_name: "t".into(),
            file_name: "t.csv".into(),
            headers: vec!["id".into()],
            row_count: 1,
            skipped_rows: 0,
            primary_key: vec!["id".into()],
            ner_tags: vec![EntityTag {
                column_name: "id".into(),
                table_name: "t".into(),
                entity_type: "PRIMARY_KEY_ID".into(),
                confidence: 0.9,
                sample_values: vec![],
                description: "Primary key identifier".into(),
            }],
            column_types: vec!["INTEGER".into()],
            value_samples: vec![],
        }];
        let md = generate_report(&tables, &[]);
        assert!(md.contains("## 1. Table schemas"));
        assert!(md.contains("`t`"));
        assert!(md.contains("No cross-table foreign keys"));
    }
}
